bool p1InsideP2 = true;
bool p2InsideP1 = true;

// Check if any vertex of P1 is outside P2's bounding box
for (const auto& p : P1.vectorPoints()) {
    if (!P2.updateBoundingBox().contains(p)) {
        p1InsideP2 = false;
        break;
    }
}

// Check if any vertex of P2 is outside P1's bounding box
for (const auto& p : P2.vectorPoints()) {
    if (!P1.updateBoundingBox().contains(p)) {
        p2InsideP1 = false;
        break;
    }
}

// If one polygon is completely inside the other, they intersect
if (p1InsideP2 || p2InsideP1)
    return true;

// Check for edge intersections
for (size_t i = 0; i < P1.size(); ++i) {
    cg3::Point2d A = P1[i];
    cg3::Point2d B = P1[(i + 1) % P1.size()];

    for (size_t j = 0; j < P2.size(); ++j) {
        cg3::Point2d C = P2[j];
        cg3::Point2d D = P2[(j + 1) % P2.size()];

        // Check if segments AB and CD intersect
        // Using cross product method for line segment intersection
        cg3::Point2d AB = B - A;
        cg3::Point2d AC = C - A;
        cg3::Point2d AD = D - A;

        double cross1 = AB.perpendicularDot(AC);
        double cross2 = AB.perpendicularDot(AD);

        if (cross1 * cross2 > 0) // Points C and D are on the same side of line AB
            continue;

        cg3::Point2d CD = D - C;
        cg3::Point2d CA = A - C;
        cg3::Point2d CB = B - C;

        double cross3 = CD.perpendicularDot(CA);
        double cross4 = CD.perpendicularDot(CB);

        if (cross3 * cross4 > 0) // Points A and B are on the same side of line CD
            continue;

        // Segments intersect
        return true;
    }
}

return false;

